def solve_with_resultant():
    """
    使用 Resultant 方法
    
    p = pp² + 3pp + 3
    q = pp² + 5pp + 7
    
    消去 pp 得到 p 和 q 的关系:
    
    从 p = pp² + 3pp + 3，解出 pp:
    pp = (-3 + sqrt(9 - 4(3-p))) / 2 = (-3 + sqrt(4p - 3)) / 2
    
    代入 q 的表达式... 这会得到 p 和 q 的代数关系
    
    Resultant(pp² + 3pp + 3 - p, pp² + 5pp + 7 - q, pp) = 0
    给出 p 和 q 满足的方程
    """
    # 计算 resultant
    # f = pp² + 3pp + (3-p)
    # g = pp² + 5pp + (7-q)
    # 
    # Resultant = (3-p)(7-q) - (3pp+3-p)(5pp+7-q) 的某种组合
    # 
    # 更简单：直接计算
    # f - g = -2pp - 4 + (q - p) = 0
    # 所以 q - p = 2pp + 4, 即 pp = (q - p - 4) / 2
    # 
    # 代入 p = pp² + 3pp + 3:
    # p = ((q-p-4)/2)² + 3(q-p-4)/2 + 3
    # 4p = (q-p-4)² + 6(q-p-4) + 12
    # 4p = (q-p)² - 8(q-p) + 16 + 6(q-p) - 24 + 12
    # 4p = (q-p)² - 2(q-p) + 4
    # 4p = q² - 2pq + p² - 2q + 2p + 4
    # 0 = q² - 2pq + p² - 2q + 2p + 4 - 4p
    # 0 = q² - 2pq + p² - 2q - 2p + 4
    # 0 = (q - p)² - 2(q + p) + 4
    # (q - p)² = 2(p + q) - 4
    #
    # 设 s = p + q, d = q - p
    # d² = 2s - 4
    # s = (d² + 4) / 2
    #
    # 又 p*q = s²/4 - d²/4 = (s² - d²)/4 = (s-d)(s+d)/4 = p*q ✓ (恒等式)
    # 
    # 但我们还有 n = p*q*r
    # 设 P = p*q = n/r
    # 
    # p*q = P
    # p + q = s = (d² + 4) / 2
    # 
    # p 和 q 是方程 t² - st + P = 0 的根
    # t = (s ± sqrt(s² - 4P)) / 2
    
    # 从 d² = 2s - 4 和 s² - 4P 需要是完全平方
    # s² - 4P ≥ 0, 且 s² - 4P = d² (因为 (p-q)² = (p+q)² - 4pq)
    # 
    # 所以 d² = s² - 4P
    # 代入 d² = 2s - 4:
    # 2s - 4 = s² - 4P
    # s² - 2s + (4 - 4P) = 0
    # s = (2 ± sqrt(4 - 4(4-4P))) / 2 = 1 ± sqrt(1 - 4 + 4P) = 1 ± sqrt(4P - 3)
    # 
    # 由于 s = p + q > 0, 取 s = 1 + sqrt(4P - 3)
    # 
    # 验证: 4P - 3 需要是完全平方数！
    # 
    # 设 4P - 3 = k², 则 P = (k² + 3) / 4
    # 需要 k² + 3 ≡ 0 (mod 4), 即 k² ≡ 1 (mod 4), 即 k 是奇数
    
    print("使用 Resultant 方法:")
    print("设 P = p*q = n/r")
    print("需要 4P - 3 是完全平方数，设为 k²")
    print("则 s = p + q = 1 + k")
    print("d = q - p, d² = 2s - 4 = 2k - 2")
    print()
    
    # 遍历可能的 r 值
    # r 应该是素数，且 n % r == 0
    # 
    # n/r = P，4P - 3 应该是完全平方
    # 4n/r - 3 = k²
    # 4n - 3r = k² * r
    # 
    # 这意味着 r | (4n - 3r) 对某些 k 成立... 不太有用
    
    # 更好：遍历 k (k 大约是 sqrt(4P) ≈ 2*sqrt(p*q) ≈ 2p)
    # 如果 k² + 3 = 4P，且 P | n，且 n/P 是素数
    
    print("遍历可能的 k 值...")
    # k² ≈ 4P ≈ 4n/r
    # 如果 r 大约 512 bit，P 大约 1024 bit，k 大约 512 bit
    # 这太大了，不能直接遍历
    
    # 但是！pp 相对较小
    # pp² + 3pp + 3 = p, pp² + 5pp + 7 = q
    # p ≈ pp², q ≈ pp²
    # P = pq ≈ pp⁴
    # k² = 4P - 3 ≈ 4pp⁴
    # k ≈ 2pp²
    
    # 所以遍历 pp 等价于遍历 k
    
    # 让我们估算 pp 的大小
    # n 约 1536 bit
    # 如果 r 约 512 bit，则 P = pq 约 1024 bit
    # p ≈ q ≈ pp²，所以 pp⁴ ≈ P，pp 约 256 bit
    
    print(f"n 的比特长度: {n.bit_length()}")
    # 1536 bits 的 n，如果 r 512 bit，P 1024 bit，pp 256 bit
    # 256 bit 太大，不能爆破
    
    # 但如果 pp 设计得比较小 (CTF 通常这样)...
    # 继续尝试

# 让我们用更聪明的方法：检查 n 的特殊结构
def analyze_n():
    print(f"n = {n}")
    print(f"n bits = {n.bit_length()}")
    print(f"n mod 4 = {n % 4}")
    print(f"n mod 8 = {n % 8}")
    
    # 尝试 Pollard rho
    print("\n尝试 Pollard's rho 分解...")
    
    def pollard_rho(n, max_iter=10**7):
        if n % 2 == 0:
            return 2
        x = 2
        y = 2
        d = 1
        f = lambda x: (x * x + 1) % n
        
        count = 0
        while d == 1 and count < max_iter:
            x = f(x)
            y = f(f(y))
            d = gcd(abs(x - y), n)
            count += 1
            if count % 1000000 == 0:
                print(f"  Pollard rho iteration: {count}")
        
        if d != n:
            return d
        return None
    
    factor = pollard_rho(n)
    if factor:
        print(f"Found factor: {factor}")
        return factor
    else:
        print("Pollard rho failed")
    
    return None

